const canvas = document.querySelector("#canvas");
if (!canvas || !canvas.getContext) {
  console.error("Canvas not supported or not found");
} else {
  const ctx = canvas.getContext("2d");

  // Set canvas size with device pixel ratio
  function setCanvasSize() {
    canvas.width = window.innerWidth * (window.devicePixelRatio || 1);
    canvas.height = window.innerHeight * (window.devicePixelRatio || 1);
    ctx.scale(window.devicePixelRatio || 1, window.devicePixelRatio || 1);
  }
  setCanvasSize();

  // Configuration
  const config = {
    bubbles: { count: 50, minRadius: 2, maxRadius: 7, vyMin: 0.5, vyMax: 1 },
    plankton: { count: 100, minRadius: 0.5, maxRadius: 1.5, vMax: 0.2 },
    jellyfish: { count: 30, minRadius: 10, maxRadius: 30, vyMin: -0.7, vyMax: -0.2 },
  };

  const bubbles = [];
  const plankton = [];
  const jellyfish = [];

  // Factory function for creating objects
  function createObject(x, y, vx, vy, radius, color) {
    return { x, y, vx, vy, radius, color };
  }

  // Initialize objects
  function initializeScene() {
    bubbles.length = 0;
    plankton.length = 0;
    jellyfish.length = 0;

    for (let i = 0; i < config.bubbles.count; i++) {
      bubbles.push(
        createObject(
          Math.random() * canvas.width,
          canvas.height + Math.random() * canvas.height,
          (Math.random() - 0.5) * 0.8,
          Math.random() * (config.bubbles.vyMax - config.bubbles.vyMin) + config.bubbles.vyMin,
          Math.random() * (config.bubbles.maxRadius - config.bubbles.minRadius) + config.bubbles.minRadius,
          "darkblue"
        )
      );
    }

    for (let i = 0; i < config.plankton.count; i++) {
      plankton.push(
        createObject(
          Math.random() * canvas.width,
          Math.random() * canvas.height,
          (Math.random() - 0.5) * config.plankton.vMax,
          (Math.random() - 0.5) * config.plankton.vMax,
          Math.random() * (config.plankton.maxRadius - config.plankton.minRadius) + config.plankton.minRadius,
          "blue"
        )
      );
    }

    for (let i = 0; i < config.jellyfish.count; i++) {
      jellyfish.push(
        createObject(
          Math.random() * canvas.width,
          canvas.height + Math.random() * canvas.height,
          (Math.random() - 0.5) * 0.5,
          Math.random() * (config.jellyfish.vyMax - config.jellyfish.vyMin) + config.jellyfish.vyMin,
          Math.random() * (config.jellyfish.maxRadius - config.jellyfish.minRadius) + config.jellyfish.minRadius,
          "rgba(255, 0, 255, 0.2)"
        )
      );
    }
  }

  // Wrap-around helper
  function wrapAround(obj, vertical = false) {
    if (obj.x < 0) obj.x = canvas.width;
    if (obj.x > canvas.width) obj.x = 0;
    if (vertical) {
      if (obj.y < -obj.radius) obj.y = canvas.height + obj.radius;
      if (obj.y > canvas.height + obj.radius) obj.y = -obj.radius;
    } else {
      if (obj.y < 0) obj.y = canvas.height;
      if (obj.y > canvas.height) obj.y = 0;
    }
  }

  // Update and draw functions
  function updateBubble(bubble) {
    bubble.x += bubble.vx;
    bubble.y -= bubble.vy;
    wrapAround(bubble, true);
  }

  function updatePlankton(p) {
    p.x += p.vx;
    p.y += p.vy;
    wrapAround(p);
  }

  function updateJellyfish(j) {
    j.x += j.vx;
    j.y += j.vy;
    wrapAround(j, true);
  }

  function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw bubbles
    ctx.fillStyle = "darkblue";
    ctx.beginPath();
    bubbles.forEach((bubble) => {
      updateBubble(bubble);
      ctx.moveTo(bubble.x, bubble.y);
      ctx.arc(bubble.x, bubble.y, bubble.radius, 0, Math.PI * 2);
    });
    ctx.fill();

    // Draw plankton
    ctx.fillStyle = "blue";
    ctx.beginPath();
    plankton.forEach((p) => {
      updatePlankton(p);
      ctx.moveTo(p.x, p.y);
      ctx.arc(p.x, p.y, p.radius, 0, Math.PI * 2);
    });
    ctx.fill();

    // Draw jellyfish
    ctx.fillStyle = "rgba(255, 0, 255, 0.2)";
    ctx.beginPath();
    jellyfish.forEach((j) => {
      updateJellyfish(j);
      ctx.moveTo(j.x, j.y);
      ctx.arc(j.x, j.y, j.radius, 0, Math.PI * 2);
    });
    ctx.fill();

    requestAnimationFrame(draw);
  }

  // Resize handler
  window.addEventListener("resize", () => {
    setCanvasSize();
    initializeScene(); // Reset objects on resize
  });

  // Start the animation
  initializeScene();
  draw();
}
